client_script:
frappe.web_form.after_load = () => {  
    // URL is supplied as http://0.0.0.0:8000/project-feedback-ex/new?project=eere
    const project = new URLSearchParams(window.location.search).get('project');  
    frappe.web_form.set_value('project', project); 
    //set readonly 
    frappe.web_form.set_df_property('project', 'hidden', true); //set to hidden as read only mode will show the project id
    frappe.web_form.set_df_property('project_name', 'read_only', true);
}

frappe.web_form.on('project', (field, value) => {
    frappe.web_form.set_value('project_name', ''); 
    const project = new URLSearchParams(window.location.search).get('project'); 
	frappe.call({ 
	   "method": "project_monitor.project_monitor.web_form.project_feedback_ex.project_feedback_ex.get_project_name",
		args: { 
			"project": project, //value
		},
		callback: function(data){				
		    //set project values
		    frappe.web_form.set_value('subject', data.message.project_name);
		    frappe.web_form.set_value('project_name', data.message.project_name);
			frappe.web_form.refresh();
		}
	});
});
